const D = { energy: .62, density: .55, speed: 1, scale: 1, twist: .55, hue: 210, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
if (!S.sx) { S.sx = new Float32Array(72); S.sy = new Float32Array(72); }

const style = P.style;
const u = Math.min(width, height);
const cx = P.x * width, cy = P.y * height;
const R = u * 0.30 * P.scale;
const glow = 0.35 + P.energy * 0.95;
const spd = 0.2 + P.speed;
const twist = P.twist;
const alphaF = P.alpha / 100;
const additive = style !== 'ink';

// ---- seed-driven layout offsets (deterministic) ----
const hueOff = fr(9) * 360;
const jTh = (fr(3) - 0.5) * 0.16;
const jPh = fr(7) * 6.2831853;

// ---- fiber counts (density = 2nd param, drives ring population) ----
const nLat = 2 + Math.round(P.density * 2.2);            // 2..4
const nLon = Math.round(6 + P.density * 12);             // 6..18
const nFib = nLat * nLon;
let pts = Math.round(2200 / nFib); if (pts < 20) pts = 20; if (pts > 46) pts = 46;

// ---- dramaturgy: hue sweep + spin build across sections ----
const secHue = K.section * 17;
const intens = 0.7 + 0.3 * K.intensity + A.bass * 0.5;
const secSpin = 1 + K.section * 0.04;

// ---- continuous 4D rotation of S^3 (the motion floor) ----
const a4 = K.t * 0.13 * spd * secSpin;
const b4 = K.t * 0.19 * spd + 1.7;
const c4 = K.t * 0.075 * spd * twist;
const ca = Math.cos(a4), sa = Math.sin(a4), cb = Math.cos(b4), sb = Math.sin(b4), cc = Math.cos(c4), sc = Math.sin(c4);
// slow 3D view tumble
const ry = K.t * 0.045 * spd + 0.6, rx = 0.52;
const cry = Math.cos(ry), sry = Math.sin(ry), crx = Math.cos(rx), srx = Math.sin(rx);

// ---- background wash (fills the frame; alpha lets it composite) ----
push();
noStroke();
let bgH, bgS, bgB;
if (style === 'ink') { bgH = 40; bgS = 8; bgB = 92; }
else if (style === 'ice') { bgH = 215; bgS = 55; bgB = 7; }
else if (style === 'gold') { bgH = 30; bgS = 40; bgB = 6; }
else { bgH = (P.hue + secHue + 260) % 360; bgS = 55; bgB = 6; }
fill(bgH, bgS, bgB, P.alpha);
rect(0, 0, width, height);

// ---- ambient core glow so the frame never reads 80% black ----
if (additive) {
  blendMode(ADD);
  const ag = (0.4 + P.energy * 0.5) * intens * alphaF;
  const ah = (P.hue + secHue + hueOff) % 360;
  for (let r = 0; r < 3; r++) {
    fill(ah, style === 'ice' ? 40 : 60, style === 'gold' ? 70 : 85, 5 * ag * (3 - r));
    ellipse(cx, cy, u * (1.5 - r * 0.4) * P.scale, u * (1.5 - r * 0.4) * P.scale);
  }
}

// ---- draw the fibers ----
noFill();
if (additive) blendMode(ADD); else blendMode(BLEND);

for (let li = 0; li < nLat; li++) {
  const theta = 0.20 * Math.PI + (li + 0.5) / nLat * 0.60 * Math.PI + jTh;
  const ch = Math.cos(theta / 2), sh = Math.sin(theta / 2);
  for (let ki = 0; ki < nLon; ki++) {
    const phi = ki / nLon * 6.2831853 + jPh + li * 0.4;
    const phiDeg = ki / nLon * 360;
    // build projected ring
    let mz = 0;
    for (let p = 0; p < pts; p++) {
      const tt = p / pts * 6.2831853;
      let X = ch * Math.cos(tt);
      let Y = ch * Math.sin(tt);
      let Z = sh * Math.cos(tt + phi);
      let W = sh * Math.sin(tt + phi);
      // 4D plane rotations (X,Z),(Y,W),(X,W)
      let t1 = X * ca - Z * sa; Z = X * sa + Z * ca; X = t1;
      let t2 = Y * cb - W * sb; W = Y * sb + W * cb; Y = t2;
      let t3 = X * cc - W * sc; W = X * sc + W * cc; X = t3;
      // stereographic projection from north pole (W=1)
      let Wc = W > 0.94 ? 0.94 : W;
      const f = 1 / (1 - Wc);
      let X3 = X * f, Y3 = Y * f, Z3 = Z * f;
      const mag = Math.sqrt(X3 * X3 + Y3 * Y3 + Z3 * Z3);
      if (mag > 6) { const s6 = 6 / mag; X3 *= s6; Y3 *= s6; Z3 *= s6; }
      // 3D view rotation (around Y, then X)
      let vx = X3 * cry - Z3 * sry; let vz = X3 * sry + Z3 * cry;
      let vy = Y3 * crx - vz * srx; let vz2 = Y3 * srx + vz * crx;
      S.sx[p] = cx + vx * R;
      S.sy[p] = cy + vy * R;
      mz += vz2;
    }
    mz /= pts;
    const depth = Math.max(0, Math.min(1, (mz + 2.5) / 5));

    // color by style
    let h, s;
    if (style === 'gold') { h = (40 + 10 * Math.sin(phi) + secHue) % 360; s = 72; }
    else if (style === 'ice') { h = (188 + 18 * Math.sin(phi * 2) + secHue * 0.3 + 360) % 360; s = 42; }
    else if (style === 'ink') { h = 0; s = 0; }
    else { h = (P.hue + phiDeg + hueOff + secHue) % 360; s = style === 'neon' ? 96 : 82; }

    if (style === 'ink') {
      // wireframe blueprint: thin dark contour lines on pale paper
      stroke(0, 0, 14, (42 + 24 * depth) * alphaF);
      strokeWeight(Math.max(0.8, u * 0.0016 * (0.7 + 0.6 * depth)));
      beginShape();
      for (let p = 0; p < pts; p++) vertex(S.sx[p], S.sy[p]);
      endShape(CLOSE);
    } else {
      // additive two-pass glow tube
      const haloB = style === 'ice' ? 80 : 62;
      const coreB = style === 'neon' ? 100 : 94;
      const aHalo = glow * intens * alphaF * (style === 'ice' ? 7 : 9) * (0.45 + 0.55 * depth);
      const aCore = glow * intens * alphaF * (style === 'neon' ? 34 : 26) * (0.5 + 0.5 * depth) + A.treble * 22 * alphaF;
      const wHalo = Math.max(1, u * 0.011 * glow * (0.45 + 0.6 * depth));
      const wCore = Math.max(0.8, u * 0.0032 * (0.7 + 0.5 * depth));
      // halo
      stroke(h, s * 0.85, haloB, aHalo);
      strokeWeight(wHalo);
      beginShape();
      for (let p = 0; p < pts; p++) vertex(S.sx[p], S.sy[p]);
      endShape(CLOSE);
      // core
      stroke(h, s, coreB, aCore);
      strokeWeight(wCore);
      beginShape();
      for (let p = 0; p < pts; p++) vertex(S.sx[p], S.sy[p]);
      endShape(CLOSE);
    }
  }
}
blendMode(BLEND);
pop();
